<script setup>import TwinalyzeAnalytics from '@twinalyze/web-analytics';import {onMounted,ref} from 'vue';const status=ref('Ready for testing'),eventName=ref('testingLabAction'),identifyEmail=ref('lab.user@example.com'),permission=ref('unsupported');onMounted(()=>permission.value='Notification'in window?Notification.permission:'unsupported');const event=()=>{TwinalyzeAnalytics.track(eventName.value,{action:'demo_button_clicked',page:'testing_lab',framework:'Vue',integration:'npm',source:'nivora_vue_npm_store',timestamp:new Date().toISOString()});status.value=`Requested event: ${eventName.value}`;};const identify=()=>{const email=identifyEmail.value.trim().toLowerCase();TwinalyzeAnalytics.identify(email,{email,name:'Testing Lab User',accountType:'tester',authenticationEvent:'manual_identify',source:'nivora_vue_npm_store'});status.value=`Requested identify for ${email}`;};const notifications=async()=>{if(!('Notification'in window)){status.value='Notifications unsupported';return;}if(Notification.permission==='denied'){permission.value='denied';status.value='Blocked in browser settings';return;}permission.value=await Notification.requestPermission();status.value=`Notification permission: ${permission.value}`;};const local=async()=>{if(Notification.permission!=='granted'){status.value='Allow notifications first';return;}try{const reg=await navigator.serviceWorker.ready;await reg.showNotification('Nivora notification test',{body:'Browser permission and worker are working.',icon:'/favicon.svg',data:{clickURL:'/testing-lab'}});status.value='Local notification displayed';}catch(e){new Notification('Nivora notification test',{body:'Browser permission is working.',icon:'/favicon.svg'});status.value=String(e);}};const worker=async()=>{try{const response=await fetch('/twinalyze-fcm-sw.js',{cache:'no-store'});const regs=await navigator.serviceWorker.getRegistrations();const registered=regs.some(r=>[r.active,r.installing,r.waiting].some(w=>w?.scriptURL.includes('twinalyze-fcm-sw.js')));status.value=`Worker URL ${response.status}; registered: ${registered}`;}catch(e){status.value=`Worker check failed: ${String(e)}`;}};const location=()=>navigator.geolocation?.getCurrentPosition(()=>status.value='Location allowed',e=>status.value=e.message);</script>
<template><section class="page"><div><span>NIVORA / TESTING LAB</span><h1>Test every signal.</h1><p>Use this area for direct events, identify, browser permissions, the FCM worker, downloads, and scroll-depth measurement.</p></div><div class="status"><strong>Current status</strong><span>{{status}}</span></div><div class="grid"><article class="coral"><span>01</span><h2>Custom event</h2><p>Sends a direct npm track call.</p><input v-model="eventName"/><button @click="event">Send event</button></article><article class="cream"><span>02</span><h2>Identify</h2><p>Uses email as userId.</p><input v-model="identifyEmail" type="email"/><button @click="identify">Identify user</button></article><article class="sage"><span>03</span><h2>Notifications</h2><p>Permission: <strong>{{permission}}</strong></p><button @click="notifications">Enable notifications</button><button class="secondary" @click="local">Local test</button></article><article class="blue"><span>04</span><h2>FCM worker</h2><p>Check root URL and registration.</p><button @click="worker">Check worker</button><a href="/twinalyze-fcm-sw.js" target="_blank">Open worker</a></article><article class="sand"><span>05</span><h2>Download</h2><p>Download a ZIP from public.</p><a class="dark" href="/downloads/nivora-test-download.zip" download>Download ZIP</a></article><article class="lilac"><span>06</span><h2>Location</h2><p>Trigger another permission flow.</p><button @click="location">Request location</button></article></div><section class="scroll"><div><span>SCROLL DEPTH</span><h2>Keep going.</h2></div><b>↓</b><div><h3>You reached the lower marker.</h3><p>With enhanced measurement enabled, scroll depth should be recorded.</p></div></section></section></template>
<style scoped>.page{padding:70px 6vw}.page>div:first-child>span,article>span,.scroll span{color:var(--coral-dark);font-size:10px;font-weight:900;letter-spacing:.18em}h1{margin:13px 0;font:400 clamp(58px,7vw,96px)/.9 Georgia}.page>div:first-child p{max-width:780px;color:var(--muted);line-height:1.7}.status{margin-top:26px;padding:17px 20px;display:flex;justify-content:space-between;border-radius:15px;background:var(--ink);color:white}.grid{margin-top:22px;display:grid;grid-template-columns:repeat(3,1fr);gap:14px}article{min-height:275px;padding:24px;display:flex;flex-direction:column;border-radius:25px}.coral{background:var(--coral)}.cream{background:var(--cream)}.sage{background:var(--sage)}.blue{background:var(--blue)}.sand{background:#dfcfaa}.lilac{background:#d4c6dd}article h2{margin:14px 0 7px;font:400 30px Georgia}article p{color:#555c54;line-height:1.55}input{width:100%;box-sizing:border-box;margin-top:auto;margin-bottom:9px;padding:12px;border:1px solid rgba(31,35,31,.25);border-radius:999px;background:rgba(255,255,255,.5)}article button,article a{margin:4px 4px 0 0;padding:11px 14px;border:0;border-radius:999px;background:var(--ink);color:white;font-weight:800;text-align:center}.secondary,article a:not(.dark){background:rgba(255,255,255,.5);color:var(--ink)}.scroll{min-height:1000px;margin-top:30px;padding:52px;display:flex;flex-direction:column;justify-content:space-between;align-items:center;border-radius:34px;background:linear-gradient(var(--cream),var(--blue));text-align:center}.scroll h2{font:400 clamp(56px,8vw,108px) Georgia}.scroll>b{font-size:100px}.scroll h3{font:400 38px Georgia}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){.page{padding-inline:20px}.grid{grid-template-columns:1fr}.status{display:grid;gap:8px}.scroll{padding-inline:18px}}</style>
